  /// Returns a new syntax node that has the child at `keyPath` replaced by
  /// `value`.
  public func with<T>(_ keyPath: WritableKeyPath<
Self,
 T>,
 _ value: T) -> Self
    var copy = self
    copy[keyPath: keyPath] = value
    return copy
  }

  /// Return this subtree with this node as the root,
 ie. detach this node
  /// from its parent.
  public var detached: Self {
    if !self.hasParent
{
      return self
    }
    // Make sure `self` (and thus the arena of `self.raw`) can’t get deallocated
    // before the detached node can be created.
    return withExtendedLifetime(self) {
      return Syntax(raw: self.raw,
 rawNodeArena: self.raw.arenaReference.retained).cast(Self.self)
    }
  }
})b"

